type Topic={intro:[string,string];study:string[];practice:string[];source:'python'|'ml'|'torch'|'hf'|'training';section:string;read:string;action:string;studyTask:string;task:string;input:string;expected:string;hint:string;pitfalls:[string,string];code?:string};
const urls={python:'https://docs.python.org/3/tutorial/',ml:'https://developers.google.com/machine-learning/crash-course',torch:'https://docs.pytorch.org/tutorials/beginner/basics/intro.html',hf:'https://huggingface.co/learn/llm-course/en/chapter1/1',training:'https://huggingface.co/docs/transformers/main/training'};
const titles={python:'Python Tutorial',ml:'Google Machine Learning Crash Course',torch:'PyTorch Learn the Basics',hf:'Hugging Face LLM Course',training:'Hugging Face Fine-tuning Guide'};
const topics:Topic[]=[
{intro:['Python در این مسیر ابزار خواندن داده و آزمایش مدل است. متغیر نامی برای یک مقدار است؛ عدد 30 و رشته "30" یکسان نیستند. شرط تصمیم می‌گیرد کدام بخش اجرا شود و تورفتگی مرز بلوک را مشخص می‌کند. اول اجرای فایل ساده را یاد بگیر تا خطای نصب را با خطای کد اشتباه نگیری.','فایل Python از بالا به پایین اجرا می‌شود ولی Notebook حافظه اجرای سلول‌های قبلی را نگه می‌دارد. اجرای بی‌ترتیب ممکن است متغیری پنهان بسازد؛ Restart و Run All باید همان خروجی را از محیط پاک تولید کند.'],study:['در Windows دستور py --version و در Linux/macOS دستور python3 --version را اجرا کن. نسخه و مسیر مفسر را ثبت کن؛ اگر نصب نیست از نصب‌کننده رسمی Python استفاده کن.','در Windows با py -m venv .venv و در Linux/macOS با python3 -m venv .venv محیط مجزا بساز. بدون تغییر تنظیمات PowerShell می‌توانی مستقیم .venv\\Scripts\\python.exe را اجرا کنی؛ در Unix مسیر .venv/bin/python است.','در hello.py مقدار minutes=90 را تعریف کن، hours=minutes/60 را حساب و چاپ کن. سپس مقدار را به 30 تغییر بده و پیش از اجرا خروجی را پیش‌بینی کن.','با if minutes >= 60 پیام long و در غیر این صورت short چاپ کن. با دو ورودی هر دو شاخه را ببین و فرق = و == را توضیح بده.'],practice:['با مفسر همان محیط دستور -m pip install notebook و سپس -m notebook را اجرا کن. نصب و اجرای Jupyter باید از یک محیط باشند؛ در مرورگر فقط آدرس محلی چاپ‌شده ترمینال را باز کن.','پنج سلول برای دقیقه به ساعت، ساعت به دقیقه، KB اعشاری به بایت، سانتی‌متر به متر و سلسیوس به فارنهایت بساز؛ ورودی عددی و print نتیجه در هر سلول باشد.','یک سلول Markdown با فرمول و فرض هر تبدیل اضافه کن. بنویس KB با فرض 1000 است و با KiB یکی نیست. یک شرط long/short هم در سلول جدا اجرا کن.','Kernel را restart و همه سلول‌ها را به ترتیب اجرا کن. هر NameError ناشی از متغیر اجرای قبلی را اصلاح و Notebook را ذخیره کن.'],source:'python',section:'An Informal Introduction to Python؛ More Control Flow Tools: if Statements',read:'فقط Numbers، Strings، انتساب و if را بخوان؛ کلاس و decorator فعلاً لازم نیست.',action:'مثال عدد، رشته و شرط را در فایل خودت بدون کپی بازنویسی کن و نتیجه دو ورودی را پیش‌بینی کن.',studyTask:'اسکریپتی بساز که minutes را به hours تبدیل کند و برای 60 دقیقه یا بیشتر long چاپ کند.',task:'دفترچه پنج تبدیل واحد را از محیط پاک اجرا کن.',input:'90 دقیقه؛ 2 ساعت؛ 3KB اعشاری؛ 250 سانتی‌متر؛ 20°C',expected:'1.5 ساعت؛ 120 دقیقه؛ 3000 بایت؛ 2.5 متر؛ 68°F. با minutes=30 پیام short است؛ Run All هیچ NameError ندارد.',hint:'فرمول F=C*9/5+32 است. با مسیر کامل مفسر محیط مجزا جلوی نصب بسته در محیط اشتباه را بگیر.',pitfalls:['رشته "30" عدد 30 نیست؛ تبدیل نوع را آگاهانه انجام بده.','اجرای موفق سلول‌ها پس از اجرای بی‌ترتیب، بازتولیدپذیری Notebook را ثابت نمی‌کند.'],code:'minutes = 90\nprint(minutes / 60)\nif minutes >= 60:\n    print("long")\nelse:\n    print("short")'},
{intro:['List دنباله‌ای مرتب از داده‌ها و Dictionary مجموعه مقدارهای قابل دسترسی با کلید است. یک Task می‌تواند Dictionary با title، done و minutes باشد؛ List چند Task را نگه می‌دارد. حلقه هر رکورد را می‌خواند و شرط فقط موارد مورد نظر را انتخاب می‌کند.','تابع summarize باید ورودی و خروجی مشخص داشته باشد و به متغیر global وابسته نباشد. در فهرست خالی تقسیم بر تعداد رکوردها ممکن نیست؛ قراردادی مثل میانگین صفر را پیش از تقسیم پیاده کن و آن را به کاربر توضیح بده.'],study:['سه Dictionary با title، done بولی و minutes عددی در یک List بساز. tasks[0]["title"] را چاپ کن و فرق index با کلید را توضیح بده.','با for task in tasks عنوان‌ها را چاپ کن؛ سپس شرط if task["done"] بگذار تا فقط کارهای تمام‌شده چاپ شوند.','تابع completed_count(tasks) بنویس که شمارنده محلی را از صفر شروع و پس از حلقه return کند.','تابع را با [] اجرا کن و علت نتیجه صفر را توضیح بده. accesses به tasks[0] باید برای فهرست خالی guard داشته باشد.'],practice:['سه ورودی خالی، دو رکورد با مدت 20 و 40 و done متفاوت، و سه رکورد همه انجام‌شده بساز. انتظار هرکدام را قبل اجرا بنویس.','تابع summarize(tasks) باید Dictionary شامل count، completed و mean_minutes برگرداند؛ میانگین در این قرارداد از همه کارهاست.','با assert خروجی سه حالت را بررسی کن؛ تابع نباید List ورودی را تغییر بدهد.','یک رکورد را از List تا شرط done و جمع minutes دنبال کن و مسیر داده را در یادداشت شرح بده.'],source:'python',section:'Data Structures: Lists و Dictionaries؛ Defining Functions و for Statements',read:'مثال List، Dictionary، for و return را بخوان؛ اول حلقه روشن بنویس و comprehension را اختیاری نگه دار.',action:'رکورد Task خودت را بساز و تابعی با پارامتر tasks بنویس که بدون متغیر global نتیجه بدهد.',studyTask:'تابع completed_count را برای سه وضعیت True، False، True و فهرست خالی بنویس.',task:'خلاصه تعداد، وضعیت و میانگین مدت را با تابع محاسبه کن.',input:'[{"title":"read","done":True,"minutes":20},{"title":"code","done":False,"minutes":40}]',expected:'count=2، completed=1، mean_minutes=30؛ فهرست خالی هر سه مقدار را صفر می‌دهد؛ سه وضعیت True/False/True تعداد 2 دارند.',hint:'return را بعد از پایان حلقه بگذار؛ پیش از تقسیم بررسی کن count صفر نباشد.',pitfalls:['return داخل اولین دور حلقه فقط یک رکورد را پردازش می‌کند.','done="False" رشته غیرخالی و truthy است؛ وضعیت را Boolean نگه دار.'],code:'def completed_count(tasks):\n    count = 0\n    for task in tasks:\n        if task["done"]:\n            count += 1\n    return count'},
{intro:['تبدیل int("30") موفق است ولی int("abc") یک ValueError ایجاد می‌کند. تابع پردازش ورودی باید برای رشته خالی، غیرعددی و عدد منفی قرارداد مشخص داشته باشد. گرفتن خطای مورد انتظار اجازه می‌دهد پیام روشن بدهی؛ تبدیل همه خطاها به صفر داده خراب را معتبر جلوه می‌دهد.','ماژول، تابع قابل استفاده مجدد را از کد اجرای برنامه جدا می‌کند. بلوک if __name__ == "__main__" مثال‌های دستی را فقط هنگام اجرای مستقیم فعال می‌کند؛ import فایل نباید ناخواسته برنامه یا دانلود را شروع کند.'],study:['در durations.py تابع parse_minutes(text) تعریف کن؛ ابتدا strip و بررسی خالی انجام بده و برای خالی ValueError بساز.','پس از int(text)، منفی‌بودن را بررسی کن. در این قرارداد صفر معتبر است و عدد منفی خطای جدا دارد.','در main.py تابع را import کن. لایه اجرا با except ValueError پیام کاربر را نشان بدهد؛ تابع محاسبه خودش print نکند.','مثال اجرا را زیر if __name__ قرار بده؛ import durations را در process تازه اجرا کن و مطمئن شو چاپ ناخواسته ندارد.'],practice:['جدول ورودی‌های "30"،" 45 "،"0"،"" و"abc" را با انتظار موفق/خطا قبل اجرا بنویس.','سه ورودی موفق را با assert با 30، 45 و 0 مقایسه کن. فاصله اول و آخر نباید عدد را عوض کند.','برای دو ورودی خراب بررسی کن ValueError واقعاً رخ دهد؛ اگر رخ نداد آزمون را ناموفق کن. منفی را هم به‌عنوان مورد اضافه امتحان کن.','مصرف‌کننده را اجرا و متن علت خالی، غیرعددی و منفی را ثبت کن؛ except گسترده‌ای که خطای ناشناخته را می‌بلعد حذف کن.'],source:'python',section:'Errors and Exceptions: Handling Exceptions و Raising Exceptions؛ Modules',read:'شیوه گرفتن ValueError، ساخت خطا با raise و اجرای ماژول به‌صورت script را بخوان.',action:'خطای تبدیل را بازتولید کن و نشان بده کدام لایه خطا را ایجاد و کدام لایه آن را به کاربر نمایش می‌دهد.',studyTask:'قرارداد parse_minutes را با خطای رشته خالی و منفی پیاده کن.',task:'پنج ورودی جدول را در فایل آزمون مستقل بررسی کن.',input:'"30"،" 45 "،"0"،""،"abc"؛ مورد اضافه "-1"',expected:'سه نتیجه 30، 45 و 0؛ دو ValueError برای خالی و غیرعددی؛ منفی نیز رد می‌شود. import ماژول چاپ ناخواسته ندارد.',hint:'اول strip و بررسی خالی، سپس int، سپس محدوده. برای آزمون خطا از unittest یا try/except دقیق استفاده کن.',pitfalls:['except Exception: return 0 ورودی خراب را شبیه مدت معتبر صفر می‌کند.','نام فایل را json.py یا random.py نگذار؛ ماژول استاندارد هم‌نام را می‌پوشاند.'],code:'def parse_minutes(text):\n    text = text.strip()\n    if not text:\n        raise ValueError("empty duration")\n    minutes = int(text)\n    if minutes < 0:\n        raise ValueError("negative duration")\n    return minutes'},
{intro:['JSON قالب تبادل داده است، اما parse موفق فقط درستی دستور زبان آن را نشان می‌دهد. مقدار {"wrong":1} JSON معتبر است ولی List از Task نیست. پس از json.load باید نوع مجموعه و فیلدهای هر رکورد را با قرارداد برنامه بررسی کنی.','فایل را با encoding مشخص بخوان تا متن فارسی در دستگاه دیگر خراب نشود. json، pathlib و argparse در کتابخانه استاندارد هستند؛ برای هر کار لازم نیست بسته بیرونی نصب شود. نسخه Python و وابستگی خارجی واقعی را در روش اجرا ثبت کن.'],study:['نسخه Python و مسیر مفسر محیط مجزا را ثبت کن؛ فرمان -m pip --version باید همان محیط را نشان بدهد.','با Path.open(encoding="utf-8") و json.load فایل را بخوان. نبود فایل و JSONDecodeError را جدا گزارش کن.','پس از parse بررسی کن مقدار List است و هر Task دارای title رشته و done بولی است؛ ساختار نادرست را رد کن.','تابع خواندن فایل را از summarize هفته قبل جدا نگه دار تا خلاصه‌سازی بدون دسترسی فایل هم آزمون شود.'],practice:['tasks.json با سه Task و broken.json با JSON ناقص بساز؛ داده‌ها ساختگی و بدون secret باشند.','report.py مسیر فایل را از آرگومان بگیرد، داده را بخواند و count/completed را به JSON در stdout بنویسد.','فایل ناموجود، JSON ناقص و JSON با شکل نادرست را جدا اجرا کن؛ پیام خطا و exit ناموفق با گزارش موفق فرق داشته باشد.','در محیط تازه با دستور README اجرا کن؛ اگر فقط کتابخانه استاندارد لازم است، صریح بنویس وابستگی خارجی ندارد.'],source:'python',section:'Input and Output: Reading and Writing Files و json؛ Virtual Environments and Packages',read:'with، encoding، load/dump و نصب با python -m pip را بخوان؛ بخش فایل و JSON را قبل ساخت اسکریپت تمرین کن.',action:'یک JSON درست و یک JSON خراب بخوان و تفاوت parse error با schema error را با نمونه توضیح بده.',studyTask:'تابع load_tasks(path) را با parse و اعتبارسنجی شکل List و رکوردها بنویس.',task:'اسکریپت گزارش فایل JSON را با رفتار موفق و ناموفق تحویل بده.',input:'سه Task با done های true، false، true؛ فایل ناقص؛ فایل {"wrong":1}',expected:'برای فایل درست count=3 و completed=2؛ دو فایل خراب با علت متفاوت رد می‌شوند و خروجی موفق جعلی نمی‌سازند.',hint:'گزارش عددی را بعد از پایان validation چاپ کن؛ خطا به stderr و گزارش موفق به stdout برود.',pitfalls:['JSON parse موفق به معنی schema درست نیست.','خواندن فایل بدون encoding مشخص می‌تواند متن فارسی را در سیستم دیگر خراب کند.'],code:'import json\nfrom pathlib import Path\n\ndef read_json(path):\n    with Path(path).open(encoding="utf-8") as f:\n        return json.load(f)'}
,{intro:['در dataset هر سطر یک نمونه است. Feature چیزی است که هنگام پیش‌بینی در دسترس داری و label پاسخ مطلوب است. برای پیش‌بینی مدت کار هنگام ایجاد Task، نوع کار و طول توضیح می‌توانند feature باشند؛ actual_minutes پاسخی است که می‌خواهی پیش‌بینی کنی.','نشت داده وقتی رخ می‌دهد که پاسخ یا اطلاعات آینده وارد feature شود. finished_at یا مدت نهایی در زمان ایجاد Task معلوم نیست؛ استفاده از آن‌ها می‌تواند نتیجه ارزیابی را ظاهراً عالی و کاربرد واقعی را بی‌فایده کند.'],study:['زمان پیش‌بینی را یک جمله بنویس: هنگام ایجاد Task. با همین جمله تعیین کن چه ستون‌هایی در آن لحظه معلوم‌اند.','برای یک Task ستون‌های task_type، description_length، created_estimate و actual_minutes بنویس و label را جدا علامت بزن.','برای هر ستون نوع، واحد و زمان در دسترس‌شدن را ثبت کن؛ task_id صرفاً چون عدد است feature مفید نیست.','finished_at، elapsed_minutes و یادداشت پس از پایان را در جدول نشت قرار بده و دلیل حذف هرکدام را شرح بده.'],practice:['CSV بیست‌ردیفی ساختگی با id، task_type، description_length، created_estimate و actual_minutes بساز؛ رکوردها منطقی و غیرشخصی باشند.','شناسنامه ستون‌ها را با معنا، نوع، واحد، feature/label/metadata و زمان دسترس‌پذیری ثبت کن.','ستون ended_duration را کپی actual_minutes کن؛ توضیح بده چرا پاسخ را لو می‌دهد، سپس آن را از ورودی مدل حذف کن.','تعداد سطرها، داده گم‌شده، مدت منفی و دسته نامشخص را بررسی و تصمیم برخورد با هر مورد را ثبت کن.'],source:'ml',section:'Datasets؛ Numerical Data و Categorical Data؛ مفهوم feature و label',read:'در فهرست دوره مباحث داده، ویژگی و برچسب را انتخاب کن؛ روی اطلاعات در دسترس زمان پیش‌بینی تمرکز کن.',action:'جدول Task را کنار مثال منبع بگذار و نقش و زمان دسترس‌بودن هر ستون را با دلیل مشخص کن.',studyTask:'ستون‌ها را به feature، label و metadata یا نشت تقسیم کن.',task:'CSV بیست‌ردیفی و شناسنامه آن را با یک نمونه نشت توضیح‌داده‌شده بساز.',input:'type، title_length، actual_minutes، finished_at، task_id و ended_duration=actual_minutes',expected:'type و title_length ورودی مجاز؛ actual_minutes برچسب؛ finished_at و ended_duration نشت؛ task_id معمولاً metadata. ستون نشت در ورودی مدل نیست.',hint:'بپرس در لحظه ایجاد کار، بدون دانستن نتیجه آیا این مقدار را دارم؟ این تمرین هنوز نیاز به آموزش مدل ندارد.',pitfalls:['همبستگی زیاد یک ستون، مجازبودن استفاده از آن هنگام پیش‌بینی را ثابت نمی‌کند.','داده ساختگی کوچک روش را می‌آموزد و نمایندگی داده واقعی بازار را ثابت نمی‌کند.']}
,{intro:['در یادگیری نظارت‌شده نمونه‌ها پاسخ آموزشی دارند: رگرسیون پاسخ عددی مثل دقیقه و طبقه‌بندی پاسخ دسته‌ای مثل spam تولید می‌کند. یادگیری بدون نظارت، ساختار داده را بدون همان label هدف بررسی می‌کند، مثلاً گروه‌بندی شرح Task ها.','Baseline یک مرجع ساده برای مقایسه است. مدل ثابت میانگین، برای همه کارها میانگین مدت train را پیش‌بینی می‌کند؛ این مدل feature ها را نمی‌بیند. پارامتر آن mean_train است و خطای MAE متوسط قدر مطلق اختلاف پیش‌بینی و پاسخ واقعی، با واحد دقیقه است.'],study:['پیش‌بینی دقیقه، تشخیص spam، گروه‌بندی Task و تشخیص داده پرت را از نظر هدف و وجود label دسته‌بندی کن؛ تشخیص پرت بسته به داده می‌تواند نظارت‌شده یا بدون نظارت باشد.','فرمول predict(x)=mean_train را بنویس؛ نوع مدل را از مقدار پارامتر جدا کن.','خطای مطلق هر نمونه را دستی حساب و میانگین خطاها را MAE بنام؛ واحد سنجه را هم بنویس.','توضیح بده مرجع ثابت طول و نوع کار را نمی‌بیند و چرا داده کم‌تنوع محدودیت آن است.'],practice:['از train=[10,20,30] میانگین 20 را حساب کن؛ تابع fit_baseline فقط داده آموزش را بگیرد.','تابع predict بساز که برای هر تعداد ورودی همان مقدار 20 را برگرداند؛ پاسخ ارزیابی وارد این تابع نشود.','برای evaluation=[15,35] خطاهای 5 و 15 و MAE=10 را با کد و محاسبه دستی مقایسه کن.','پارامتر، id های train، روش تقسیم و سنجه را ذخیره کن تا مدل بعدی با همان مرجع مقایسه شود.'],source:'ml',section:'Linear Regression: Loss؛ مفاهیم supervised learning و مدل',read:'تفاوت regression/classification و معنای loss را بخوان؛ برای این تمرین برازش خط لازم نیست.',action:'خطای یک مدل ثابت را با اعداد خودت حساب و تفاوت «پارامتر» و «پیش‌بینی» را توضیح بده.',studyTask:'برای چهار کاربرد، نوع مسئله و وجود label را بنویس.',task:'baseline میانگین و MAE را بدون کتابخانه ML پیاده کن.',input:'train=[10,20,30] و evaluation=[15,35]',expected:'mean_train=20؛ predictions=[20,20]؛ MAE=10 دقیقه. مدت رگرسیون و spam طبقه‌بندی نظارت‌شده‌اند؛ گروه‌بندی معمولاً بدون label هدف است.',hint:'میانگین را فقط از train بگیر و هنگام ارزیابی ثابت نگه دار؛ actual ارزیابی نباید وارد fit شود.',pitfalls:['عدد پیش‌بینی‌شده را با دیدن پاسخ نمونه ارزیابی دوباره تنظیم نکن.','طبقه‌بندی و clustering فقط چون خروجی گروهی دارند یک روش واحد نیستند.'],code:'mean_train = sum([10, 20, 30]) / 3\ny_eval = [15, 35]\nmae = sum(abs(mean_train - y) for y in y_eval) / len(y_eval)\nprint(mean_train, mae)'}
,{intro:['Training پارامتر را از پاسخ‌های داده آموزش تخمین می‌زند؛ inference با پارامتر ثابت روی ورودی تازه خروجی می‌سازد. در baseline، محاسبه میانگین آموزش و برگرداندن همان میانگین برای کار جدید دو مرحله جدا هستند. تغییر mean با پاسخ نمونه ارزیابی، استقلال ارزیابی را از بین می‌برد.','تقسیم داده باید پیش از fit انجام شود. Train برای یادگیری، validation برای انتخاب تنظیم و test برای گزارش نهایی کنار گذاشته می‌شود. داده زمان‌دار ممکن است به تقسیم گذشته/آینده نیاز داشته باشد؛ تقسیم تصادفی همیشه بهترین انتخاب نیست.'],study:['دو مسیر train labels→fit→mean و new input+mean→prediction را رسم کن؛ پاسخ جدید در مسیر inference نیست.','برای CSV بیست‌نمونه‌ای id1..12 را train، 13..16 را validation و 17..20 را test انتخاب و دلیل این تقسیم تمرینی را بنویس.','در نسخه آزمایشی میانگین همه 20 رکورد را حساب کن و توضیح بده چرا این کار validation را آلوده می‌کند؛ نسخه نهایی فقط train را fit کند.','id ها را ذخیره کن و test را برای انتخاب baseline یا تنظیم بعدی استفاده نکن؛ اگر داده تکراری است فقط جدایی id کافی نیست.'],practice:['سه فایل با تعداد 12/4/4 بساز و تعداد رکوردها را قبل و بعد ذخیره بررسی کن.','mean actual_minutes فقط از 12 رکورد train محاسبه و در baseline.json ذخیره شود؛ label test در این مرحله مصرف نشود.','پارامتر ذخیره‌شده را بارگذاری و MAE validation را با همان مقدار ثابت حساب کن؛ تعدادها در گزارش باشد.','با set id ها خالی‌بودن اشتراک هر دو split را ثابت کن و تکرار محتوایی با id متفاوت را نیز بررسی کن.'],source:'ml',section:'Datasets؛ Generalization و Overfitting؛ جداسازی آموزش و ارزیابی',read:'مباحث تقسیم داده و تعمیم را بخوان؛ تفاوت نقش validation و test را با هدف انتخاب تنظیم در نظر بگیر.',action:'نمودار fit/predict و فایل id های هر تقسیم را برای baseline خودت تهیه کن.',studyTask:'محاسبه میانگین، بارگذاری پارامتر و پیش‌بینی را به training یا inference نسبت بده.',task:'سه تقسیم غیر هم پوشان و baseline قابل بارگذاری بساز.',input:'20 رکورد با id1..20؛ train1..12، validation13..16، test17..20',expected:'تعداد 12/4/4 و اشتراک خالی؛ mean تنها از 12 نمونه train؛ MAE validation با همان mean ثابت؛ هیچ label تست وارد fit نمی‌شود.',hint:'اشتراک set id ها را بررسی کن؛ برای رکوردهای محتوایی یکسان، group یا hash محتوا را هم کنترل کن.',pitfalls:['پخش نسخه‌های تکراری یک نمونه بین train و test همچنان نشت است.','تغییر seed تا رسیدن به عدد دلخواه، ارزیابی بی‌طرفانه نمی‌سازد.']}
,{intro:['گزارش آزمایش باید مسئله، داده، روش و سنجه را به هم وصل کند. جمله «مدل خوب بود» بدون واحد، تعداد نمونه و مرجع قابل بررسی نیست. در baseline مدت باید روشن باشد میانگین از کدام train آمده و خطا روی چه نمونه مستقل حساب شده است.','MAE خطای متوسط را خلاصه می‌کند ولی توزیع خطا را نشان نمی‌دهد؛ ممکن است کارهای طولانی یا یک دسته خاص همیشه بد پیش‌بینی شوند. نمونه شکست و محدودیت داده ساختگی کوچک را کنار عدد بیاور و نتیجه را به تولید واقعی تعمیم نده.'],study:['در یک بند بگو هدف پیش‌بینی actual_minutes هنگام ایجاد Task است و چه feature هایی در دسترس‌اند.','تعداد نمونه، ستون‌های feature/label، تقسیم، مدل ثابت و مقدار پارامتر را توضیح بده.','فرمول MAE با واحد دقیقه و یک سطر actual/prediction/error را دستی بنویس.','سه محدودیت مثل داده ساختگی، نمونه کم و نبود کارهای طولانی را شرح بده؛ یکی را به تصمیم استفاده‌نکردن در تولید وصل کن.'],practice:['پس از پایان تصمیم‌های baseline، test نگه‌داشته‌شده را با همان mean_train ذخیره‌شده ارزیابی کن؛ دوباره fit نکن.','برای هر test رکورد id، actual، prediction و absolute_error را ثبت و میانگین ستون خطا را حساب کن.','بدترین نمونه را پیدا کن و کم‌نماینده‌بودن نوع یا طول آن در train را به‌عنوان فرضیه بررسی کن.','گزارش نهایی باید n، mean، MAE و محدودیت داشته باشد؛ اگر ارزیابی اجرا نشده صریحاً همین را بنویس.'],source:'ml',section:'Generalization، Overfitting و تفسیر سنجه ارزیابی',read:'تعمیم و اثر مجموعه کوچک/ناهمسان را بخوان؛ سنجه را همراه زمینه و مرجع تفسیر کن.',action:'گزارش خودت را با این پرسش بازبینی کن: فرد دیگر می‌تواند از جدول سطرها همین عدد را دوباره حساب کند؟',studyTask:'ادعای «دقت 90» در مسئله مدت را با سنجه و واحد قابل بررسی اصلاح کن.',task:'جدول test و MAE baseline را به‌همراه یک نمونه شکست گزارش کن.',input:'mean_train=20 و y_test=[5,20,35]',expected:'خطاهای 15، 0، 15؛ MAE=10 دقیقه و n=3. این اعداد نمونه بررسی کدند؛ گزارش پروژه باید اعداد اجرای خودت را داشته باشد.',hint:'برای رگرسیون از «accuracy درصدی» بدون تعریف آستانه خطا استفاده نکن؛ سنجه، واحد و تعداد را بنویس.',pitfalls:['پس از دیدن test، تنظیم مدل و گزارش همان test به‌عنوان دست‌نخورده استقلال را کم می‌کند.','خطای متوسط پایین می‌تواند شکست روی یک گروه خاص را پنهان کند.']}
,{intro:['Tensor آرایه چند بعدی با shape، dtype و device است. برای batch تصویری[B,1,28,28]، B تعداد نمونه، 1 کانال خاکستری و 28×28 اندازه تصویر است. float32 معمولاً برای تصویر و int64 برای label طبقه‌بندی به‌کار می‌رود؛ این قرارداد باید پیش از شبکه روشن باشد.','Dataset یک نمونه و label آن را می‌دهد و DataLoader نمونه‌ها را در batch جمع می‌کند. مثال Learn the Basics ممکن است FashionMNIST باشد؛ پروژه این مسیر MNIST با label رقم 0..9 است. شکل مشابه تصویر، این دو مسئله را یکسان نمی‌کند.'],study:['نسخه CPU یا سازگار با دستگاه را از نصب رسمی PyTorch انتخاب کن و torch.__version__ را ثبت کن؛ برای شروع GPU لازم نیست.','یک Tensor دو بعدی بساز و shape، dtype و device را چاپ کن؛ کاربرد dtype تصویر و label را توضیح بده.','درس Datasets & DataLoaders را بخوان؛ در مثال، dataset را به torchvision.datasets.MNIST تغییر بده و دانلود را با اقدام خودت انجام بده.','با batch32 یک batch بگیر و shape تصاویر و labels را چاپ کن؛ آخرین batch ممکن است کوچک‌تر باشد.'],practice:['Tensor2×3 و 3×2 بساز؛ پیش از matmul ابعاد خروجی 2×2 را پیش‌بینی کن و با عملیات عضو به‌عضو مقایسه کن.','آرایه 6 عضوی را به 2×3 reshape کن؛ تلاش 2×4 باید به‌علت تعداد عناصر خطا بدهد.','پنج نمونه MNIST از train را با label نمایش بده و shape هر یک را بررسی کن؛ test را برای گزارش نهایی نگه دار.','جدول shape/dtype/device برای Tensor، reshape، matmul و batch تهیه کن و خروجی را دستی مقایسه کن.'],source:'torch',section:'Tensors؛ Datasets & DataLoaders',read:'فقط درس Tensor و Dataset/DataLoader را بخوان؛ فعلاً آموزش کامل مدل لازم نیست و FashionMNIST منبع را با MNIST تطبیق بده.',action:'یک batch را بگیر و معنای هر محور، نوع label و اختلاف ضرب ماتریسی با عضو به‌عضو را در Notebook بنویس.',studyTask:'معنای images.shape=(32,1,28,28) و labels.shape=(32,) را شرح بده.',task:'reshape، matmul و نمایش پنج رقم واقعی را اجرا کن.',input:'a=[[1,2,3],[4,5,6]]؛ b=[[1,0],[0,1],[1,1]]',expected:'a@b=[[4,5],[10,11]] با شکل 2×2؛ پنج تصویر با label0..9 و جدول ابعاد ثبت شده‌اند.',hint:'@ ضرب ماتریسی است و* ضرب عضو به‌عضو؛ torch.tensor را با dtype=torch.float32 بساز.',pitfalls:['FashionMNIST پوشاک است و MNIST رقم؛ label ها را با هم اشتباه نگیر.','reshape تعداد عناصر را تغییر نمی‌دهد و معادل جابه‌جایی معنای محور نیست.'],code:'import torch\na = torch.tensor([[1.,2.,3.],[4.,5.,6.]])\nb = torch.tensor([[1.,0.],[0.,1.],[1.,1.]])\nprint(a @ b)\nprint(a.shape, a.dtype, a.device)'}
,{intro:['لایه Linear تبدیل y=xWᵀ+b را انجام می‌دهد. وزن ضریب ورودی و bias جابه‌جایی مستقل است. تصویر 28×28 پس از Flatten، 784 ویژگی دارد و لایه آخر برای هر نمونه 10 امتیاز خام می‌سازد؛ هنوز هیچ آموزش یا تضمین accuracy وجود ندارد.','امتیاز های خام logits هستند. CrossEntropyLoss برای طبقه‌بندی تک‌برچسبی logits اعشاری و label صحیح 0..9 می‌گیرد؛ softmax دستی پیش از آن لازم نیست. argmax برای نمایش پیش‌بینی است و نباید جای logits به loss داده شود.'],study:['مسیر[B,1,28,28]→Flatten→[B,784]→Linear(784,128)→ReLU→Linear(128,10) را با ابعاد رسم کن.','مدل را با nn.Module یا Sequential تعریف کن؛ ورودی forward از پارامتر بیاید نه متغیر global.','shape وزن و bias یک Linear(3,2) را چاپ و با فرمول مقایسه کن؛ وزن 2×3 و bias2 عضوی است.','فقط یک forward اجرا کن و خروجی[B,10] را بررسی کن؛ مدل آموزش‌ندیده را موفق معرفی نکن.'],practice:['batch32 تصویر و 32label بگیر؛ logits باید 32×10 و labels باید long با shape32 باشد.','nn.CrossEntropyLoss را روی logits و labels اجرا و متناهی‌بودن آن را با torch.isfinite بررسی کن.','برای نمایش کلاس از argmax(dim=1) استفاده کن، اما loss همچنان logits اصلی را بگیرد.','در نسخه آزمایش جدا، label با ابعاد نادرست یا خروجی 9 کلاسه را امتحان و دلیل خطا را شرح بده؛ سپس نسخه صحیح را برگردان.'],source:'torch',section:'Build the Neural Network؛ Optimizing Model Parameters: Loss',read:'بخش Flatten، Linear، ReLU و logits و ورودی Loss را بخوان؛ ساخت شبکه را از آموزش وزن جدا ببین.',action:'shape تمام لایه‌های مدل خودت و ورودی درست CrossEntropyLoss را کنار مثال منبع ثبت کن.',studyTask:'تعداد پارامتر Linear(3,2) با bias=True را دستی حساب کن.',task:'یک forward و loss صحیح روی batchMNIST اجرا کن.',input:'32 تصویر خاکستری 28×28 و 32label صحیح 0..9',expected:'logits32×10؛ loss اسکالر متناهی؛ argmax32 کلاس. Linear(3,2) دارای 6 وزن و 2bias، در مجموع 8 پارامتر است.',hint:'به CrossEntropyLoss خروجی float و label نوع long بده؛ softmax یا argmax را پیش از loss نگذار.',pitfalls:['logit خام را درصد اطمینان کالیبره معرفی نکن.','argmax یا تبدیل به NumPy پیش از loss، مسیر gradient را قطع می‌کند.'],code:'from torch import nn\nmodel = nn.Sequential(nn.Flatten(), nn.Linear(784,128), nn.ReLU(), nn.Linear(128,10))\nloss_fn = nn.CrossEntropyLoss()'}
,{intro:['Gradient مشتق loss نسبت به پارامتر است. backward از گراف محاسبه gradient می‌سازد و optimizer.step پارامتر را با قانون انتخابی تغییر می‌دهد؛ backward به‌تنهایی وزن را عوض نمی‌کند. این تفکیک برای اشکال‌زدایی حلقه ضروری است.','PyTorch gradient ها را در grad جمع می‌کند؛ در آموزش معمول هر batch، zero_grad باید قبل backward انجام شود. validation بدون step است و باید با eval و no_grad اجرا شود. کم‌شدن loss آموزش تضمین بهتر شدن validation در هر epoch نیست.'],study:['برای w=2 و loss=w² مشتق 4 را دستی حساب و با requires_grad=True و backward مقایسه کن.','مقدار w و grad را قبل/بعد zero_grad، backward و step چاپ کن تا اثر هر خط روشن شود.','در SGD بدون momentum با lr=0.1 رابطه w_new=w-lr*grad مقدار 1.6 می‌دهد؛ این فرمول ساده را به Adam تعمیم نده.','حلقه train را به‌ترتیب zero_grad، forward، loss، backward، step بنویس و مسیر validation را جدا کن.'],practice:['با id ثابت 1000train و 200validation انتخاب کن؛ CPU کافی است و test کنار می‌ماند.','یک epoch با batch32 اجرا کن؛ میانگین loss را با تعداد نمونه وزن بده تا batch آخر نتیجه را منحرف نکند.','در validation از eval و no_grad استفاده کن، درست‌های argmax را بشمار و بر n تقسیم کن؛ هیچ step در این حلقه نباشد.','زمان، device، seed، train loss و validationaccuracy واقعی را ثبت کن؛ عدم بهبود را پنهان نکن.'],source:'torch',section:'Automatic Differentiation with torch.autograd؛ Optimizing Model Parameters',read:'مثال requires_grad و ترتیب zero_grad/backward/step را بخوان؛ تفاوت حلقه train و evaluation را خط‌به‌خط دنبال کن.',action:'کنار هر خط کد خودت بنویس gradient می‌سازد، پاک می‌کند یا وزن را به‌روزرسانی می‌کند.',studyTask:'یک گام SGD روی loss=w² را دستی و با PyTorch مقایسه کن.',task:'یک epochMNIST کوچک با validation مستقل اجرا کن.',input:'w=2، lr=0.1؛ برای مدل 1000train/200validation و batch32',expected:'در مثال SGD، grad=4 و w بعد step≈1.6؛ در مدل loss متناهی، accuracy بین 0 و 1 و وزن‌های ثابت در validation ثبت شوند؛ اعداد واقعی اجرای خودت را گزارش کن.',hint:'برای آزمون تغییر نکردن وزن، Tensor پارامتر را قبل validation clone و بعد مقایسه کن.',pitfalls:['loss.item عدد خارج گراف است و برای backward مناسب نیست.','جا ماندن zero_grad ناخواسته، با gradientaccumulation آگاهانه و قرارداد دار یکی نیست.'],code:'optimizer.zero_grad()\nlogits = model(images)\nloss = loss_fn(logits, labels)\nloss.backward()\noptimizer.step()'}
,{intro:['Train وزن‌ها را برازش می‌دهد، validation تنظیمات و checkpoint را انتخاب می‌کند و test برای گزارش نهایی است. اگر test را بار ها برای انتخاب LearningRate ببینی، مدل را تدریجاً به همان آزمون تنظیم کرده‌ای و دیگر گزارش مستقل نیست.','state_dict وزن‌ها و buffer های مدل را ذخیره می‌کند، نه تمام معماری و preprocessing را. reload نیازمند ساخت همان مدل و load_state_dict است؛ فقط checkpoint قابل‌اعتماد خودت را باز کن و گزینه weights_only را مطابق API نسخه نصب‌شده بررسی کن.'],study:['id های split، seed و transform را در manifest ثبت کن؛ checkpoint فقط بر اساس validation انتخاب شود.','با torch.save(model.state_dict(),"mnist-weights.pt") وزن را ذخیره و کنارش معماری، transform و نسخه بسته‌ها را بنویس.','در process تازه همان مدل را بساز و با map_location="cpu" وزن را طبق API نسخه نصب‌شده بارگذاری کن؛ model.eval لازم است.','خروجی batch ثابت قبل save و بعد reload را با torch.allclose مقایسه و اختلاف device/dtype را ثبت کن.'],practice:['checkpoint منتخب validation را ثابت کن؛ برای بهتر کردن test مدل جدید انتخاب نکن.','با eval/no_grad روی test نگه‌داشته‌شده accuracy و n را حساب کن؛ اگر subset است تعداد و دلیل را بنویس.','پنج خطای واقعی را با تصویر، label و prediction نمایش بده؛ اگر کمتر است همان تعداد واقعی را گزارش کن.','Notebook، weights، manifest و README را جمع و inference از checkpoint را در محیط تازه اجرا کن.'],source:'torch',section:'Save and Load the Model؛ Optimizing Model Parameters: evaluation loop',read:'روش state_dict، بازسازی ساختار و eval را بخوان؛ جزئیات torch.load را با نسخه نصب‌شده تطبیق بده.',action:'مدل را در process تازه روی CPU بارگذاری و خروجی batch ثابت را قبل/بعد ذخیره مقایسه کن.',studyTask:'فهرست اطلاعات لازم برای باز اجرای checkpoint و نمونه برابری خروجی را تهیه کن.',task:'مدل MNIST ذخیره‌شده را روی test نهایی ارزیابی و تحویل کن.',input:'weights منتخب validation، معماری یکسان و test کنارگذاشته‌شده',expected:'accuracy واقعی، n، seed، نمونه خطا و نتیجه allclose قبل/بعد save؛ test برای تنظیم استفاده نشده باشد.',hint:'فایل وزن به‌تنهایی transform یا split را شرح نمی‌دهد؛ metadata را کنارش نگه دار.',pitfalls:['فایل checkpoint ناشناخته می‌تواند خطرناک باشد؛ منبع نامطمئن را بارگذاری نکن.','save وزن بدون ثبت معماری و پیش‌پردازش، تحویل قابل تکرار کامل نیست.']}
,{intro:['Inference تصویری همان قرارداد پیش‌پردازش آموزش را لازم دارد. اگر آموزش با تصویر خاکستری 1×28×28 و مقیاس 0..1 بوده، دادن RGB یا مقادیر 0..255 می‌تواند خروجی را خراب کند. shape، dtype، مقیاس و transform باید قبل از فراخوانی شبکه روشن باشند.','تحلیل خطا با مشاهده نمونه آغاز می‌شود اما علت قطعی از یک عکس معلوم نمی‌شود. بد خطی، label اشتباه یا preprocessing ناسازگار فرضیه‌اند؛ برای هرکدام آزمایشی طراحی کن که تنها یک عامل را تغییر دهد و مشاهده را از توضیح جدا نگه دارد.'],study:['transform آموزش، ترتیب محور، مقیاس و dtype را از کد استخراج کن؛ اگر Normalize هست مقادیر و منشأ آن‌ها را بنویس.','تابع prepare_image بساز؛ فعلاً فقط Tensor آماده MNIST را بپذیر تا ادعای پشتیبانی از هر عکس نکنی.','وزن را یک‌بار load کن و predict را با eval/no_grad بساز؛ label واقعی نباید ورودی predict باشد.','یک sample ثابت را از مسیر DataLoader و predict عبور و نتیجه را مقایسه کن؛ اختلاف، نشانه نیاز به بررسی پیش‌پردازش است.'],practice:['پنج نمونه درست و پنج خطا را با id ثابت از ارزیابی بردار؛ اگر خطا کمتر است تعداد واقعی را صریح ثبت کن.','برای هر sample عکس، label، prediction و id ذخیره کن؛ confidence را در صورت استفاده غیرکالیبره بنام.','دو فرضیه مثل scale نادرست و ابهام رقم بنویس و برای هرکدام روش آزمون جدا مشخص کن.','روی یک sample، dtype یا scale خراب را کنترل‌شده امتحان کن؛ خطای برنامه را از شکست واقعی مدل در فهم تصویر جدا گزارش کن.'],source:'torch',section:'Transforms؛ Tensors؛ Save and Load the Model',read:'قرارداد transform و eval/no_grad را مرور کن؛ فقط پیش‌پردازش واقعاً استفاده‌شده در آموزش خودت را اعمال کن.',action:'جدول قرارداد ورودی را از کد training استخراج و دو مسیر آماده‌سازی یک sample ثابت را مقایسه کن.',studyTask:'سه ورودی از نظر shape، dtype و مقیاس را با قرارداد MNIST بسنج.',task:'گزارش ده sample و یک آزمون کنترل‌شده پیش‌پردازش تهیه کن.',input:'float32[1,1,28,28] در 0..1؛ uint8[28,28] در 0..255؛ float32[1,3,28,28]',expected:'اولی با فرض training سازگار؛ دومی نیاز به تبدیل منطبق بر training؛ سوم کانال ناسازگار. جدول خطاها مشاهده و فرضیه را جدا نگه دارد.',hint:'از خروجی یک sample علت قطعی نساز؛ پیش از مدل shape، dtype و مقیاس را چاپ کن.',pitfalls:['model.eval به‌تنهایی autograd را غیر فعال نمی‌کند.','softmax بزرگ‌تر به‌تنهایی اطمینان کالیبره یا درست‌بودن پیش‌بینی را ثابت نمی‌کند.']}
,{intro:['بازتولید یعنی معلوم باشد چه کد، داده و تنظیماتی عدد گزارش‌شده را ساخته‌اند. seed به کنترل تصادف کمک می‌کند ولی تساوی بیت‌به‌بیت در همه سخت‌افزار ها و نسخه‌ها را تضمین نمی‌کند. نسخه بسته، split، architecture و transform نیز جزء شواهد هستند.','مقایسه LearningRate باید فقط همان متغیر را تغییر دهد. اگر زمان آموزش، initialization یا داده هم زمان عوض شود نمی‌فهمی کدام عامل تفاوت ساخته است. validation برای انتخاب تنظیم به کار می‌رود و test باید دست‌نخورده بماند.'],study:['manifest شامل Python/torch/torchvision، device، seed، batch، epoch، optimizer، lr، architecture و idsplit بساز.','پیش از ساخت مدل و split، random.seed و torch.manual_seed اعمال کن؛ اگر NumPy به‌کاررفته seed آن هم ثبت شود.','بسته‌های واقعی و version لازم را ثبت کن؛ فایل انبوه بسته‌های بی‌ربط جای شرح راه‌اندازی روشن را نمی‌گیرد.','اجرای کوچک یکسان را دو بار روی CPU تکرار و اختلاف واقعی را گزارش کن؛ عدم‌تساوی را پنهان نکن.'],practice:['دو lr مثل 0.01 و 0.1 برای SGD با 1000train، 200validation، دو epoch و batch32 انتخاب کن؛ بودجه دو شاخه برابر باشد.','هر دو شاخه را از وزن initial یکسان شروع کن؛ مدل دوم نباید ادامه آموزش مدل اول باشد.','در پایانه را epoch، train loss، validationaccuracy، زمان و lr را ثبت کن؛ test وارد جدول انتخاب نشود.','بر اساس validation بگو کدام در این آزمایش بهتر بود یا شواهد کافی نیست؛ از دو اجرای کوچک بهترین lr جهان را استنتاج نکن.'],source:'torch',section:'Optimizing Model Parameters: Hyperparameters و Optimization Loop',read:'تعریف learning_rate، batch_size و epochs و روش ساخت optimizer را بخوان؛ تفاوت تنظیمات و وزن آموخته‌شده را نگه دار.',action:'دو config بساز که فقط lr در آن‌ها متفاوت است و وزن initial وس plit ثابت را بارگذاری می‌کنند.',studyTask:'اطلاعات گم‌شده گزارش «PyTorch، دو epoch، دقت 93%» را مشخص کن.',task:'دو LearningRate را با شرایط و بودجه برابر مقایسه کن.',input:'SGD با lr0.01 و 0.1؛ داده، seed، initialization و دو epoch یکسان',expected:'جدول 2 تنظیم×2epoch با سنجه واقعی؛ انتخاب فقط با validation؛ manifest کامل. عدد 93% مثال گزارش ناقص است و نتیجه پروژه نیست.',hint:'state_dict اولیه را با deepcopy یا clone مستقل ذخیره کن؛ دادن مرجع همان Tensor ها ممکن است وزن اولیه را تغییر دهد.',pitfalls:['ادامه آموزش مدل اول با Learning Rate جدید مقایسه هم‌شرایط نیست.','seed یکسان تساوی کامل روی تمام GPU/driver ها را تضمین نمی‌کند.']}
,{intro:['خطای آموزش برازش داده دیده‌شده را نشان می‌دهد؛ تعمیم رفتار روی ورودی تازه است. اگر train loss کم و validationloss زیاد شود، overfitting یک فرضیه است، اما split غلط یا کد ارزیابی خراب هم باید بررسی شوند. یک منحنی به‌تنهایی علت قطعی اثبات نمی‌کند.','برای جلوگیری از نشت، فقط id جدا کافی نیست. کپی تصویر، نسخه تغییر اندازه‌یافته آن یا پیش‌پردازشی که با همه داده fit شده می‌تواند آزمون را آلوده کند. هر transform قابل fit باید پارامترش را فقط از train بگیرد.'],study:['ازلاگ‌ها train loss و validationloss را بر اساس epoch رسم کن؛ accuracy و تعداد نمونه را جدا ببین.','overfitting، split نامناسب و preprocessing ناسازگار را با آزمایش لازم برای هرکدام مقایسه کن.','اشتراک id، تکرار محتوا و منبع پارامترهای transform را بررسی کن؛ Normalize ثابت اگر هست منشأ اعدادش ثبت شود.','شمارش کلاس‌ها و درست/غلط حداقل دو رقم را گزارش کن تا accuracy کل شکست گروهی را پنهان نکند.'],practice:['prepare_batch، train_one_epoch و evaluate را از پروژه خودت بدون نگاه به منبع با ورودی/خروجی/تغییر وضعیت شرح بده.','ابهامی مثل«آیا evaluate وزن را عوض می‌کند؟ »یا«آیا transform دو مسیر یکسان است؟ »را پیش از آزمون ثبت کن.','برای evaluate، وزن‌ها را قبل/بعد با clone مستقل مقایسه کن؛ برای transform یک sample ثابت را از دو مسیر بگذران.','پاسخ اولیه، آزمایش، نتیجه و توضیح اصلاح‌شده را به commit یا Notebook وصل کن.'],source:'torch',section:'Optimizing Model Parameters؛ Transforms؛ تفاوت train و eval',read:'چرخه train/evaluation و اثر model.train، model.eval و transform را بخوان؛ فقط پس از پاسخ خودت برای تصحیح سراغ منبع برو.',action:'فرضیه تغییر نکردن وزن در evaluate را با کد خودت آزمایش و مرجع فایل را ثبت کن.',studyTask:'الگوی کاهش train loss و افزایش validationloss را با دو توضیح رقیب تفسیر کن.',task:'برای یک ابهام واقعی کد، آزمایش شاهد دار بساز.',input:'تابع evaluate و batch ثابت؛ snapshot مستقل state_dict قبل و بعد',expected:'وزن‌ها برابر می‌مانند؛ اگر نیستند محل تغییر کشف و اصلاح شود. گزارش منحنی، فرضیه overfitting را با صحت split/eval بررسی می‌کند.',hint:'copy سطحی state_dict ممکن است به همان Tensor ها وصل بماند؛ clone یا deepcopy لازم است.',pitfalls:['trainaccuracy به‌تنهایی تعمیم را نمی‌سنجد.','انتخاب بهترین test برای تنظیم، خود ارزیابی را آلوده می‌کند.']}
,{intro:['برای سرویس کردن مدل باید Notebook به تابعی با قرارداد پایدار تبدیل شود. دامنه این تمرین Tensor شکل[B,1,28,28] و خروجی List کلاس‌های 0..9 به‌همراه model_version است؛ ادعای پشتیبانی هر عکس نکن تا پردازش آن را واقعاً نسازی.','بارگذاری checkpoint در هر درخواست زمان و حافظه اضافه مصرف می‌کند. مدل یک‌بار در startup بارگذاری می‌شود و predict فقط validation، forward و postprocess دارد. خطای ورودی با نبود checkpoint دو مشکل جدا هستند و پیام قابل‌تشخیص می‌خواهند.'],study:['schema ورودی float32[B,1,28,28]، B بین 1 و 32، مقادیر متناهی 0..1 و خروجی B کلاس+version را بنویس.','خطاهای input_shape، invalid_values و model_unavailable را جدا کن؛ ورودی بی‌حد اجازه نده.','load_model(path) را به startup و predict(model,batch) را به مصرف‌کننده محدود کن؛ log شمارش load بدون چاپ تصاویر شخصی باشد.','چند predict با batch ثابت گرم و اندازه‌گیری کن؛ زمان load را از latency تابع جدا گزارش کن.'],practice:['inference.py با تعریف مدل، load_model و predict بساز؛ import نباید download یا training را شروع کند.','یک تصویر آماده MNIST را با predict اجرا و طول خروجی 1 و کلاس 0..9 را بررسی کن.','batch دو‌تصویری باید 2 خروجی دهد؛ Tensor با 3 کانال باید قبل forward رد شود.','مدل را 1 بار load و 3 بار predict کن؛ load_count=1 و تعداد فراخوانی 3 در گزارش باشد.'],source:'torch',section:'Save and Load the Model؛ Tensors؛ Build the Neural Network',read:'load_state_dict، eval و قرارداد Tensor را بخوان؛ این منبع آموزش HTTPendpoint نیست و فعلاً تابع مستقل کافی است.',action:'load را به startup منتقل و shape/dtype/magnitude را پیش از model(batch) بررسی کن.',studyTask:'قرارداد محدود predict را با حدود ورودی و خطا بنویس.',task:'دو مثال معتبر و یک نامعتبر را از ماژول مستقل اجرا کن.',input:'batchB=1 و B=2 از MNIST؛ batch با 3 کانال یا NaN',expected:'خروجی‌ها به‌ترتیب 1 و 2 کلاس؛ کانال 3/NaN رد؛ مدل 1 بار load شده و Notebook باز لازم نیست.',hint:'برای اثبات قرارداد نیاز به HTTP نیست؛ تابع Python مستقل را اول درست کن.',pitfalls:['torch.load داخل predict، بارگذاری را برای هر مصرف تکرار می‌کند.','ورودی بدون حد می‌تواند حافظه CPU/GPU را بی‌رویه مصرف کند.']}
,{intro:['Tokenizer متن را به شناسه واحدهای واژگان تبدیل می‌کند؛ توکن الزاماً کلمه یا کاراکتر نیست. Embedding جدول برداری آموخته‌شده برای این شناسه‌هاست و اطلاعات جایگاه نیز مطابق معماری به مدل وارد می‌شود. تعداد توکن به طول توالی و مصرف حافظه ارتباط دارد.','Self-Attention اطلاعات جایگاه‌های قابل‌دیدن را با وزن‌های وابسته به ورودی ترکیب می‌کند؛ Multi-Head چند فضای محاسبه دارد. Decoder-only مولد معمولاً با ماسک علّی به توکن آینده نگاه نمی‌کند، درحالی‌که Encoder مثل BERT قرارداد دید و هدف آموزش متفاوت دارد.'],study:['مسیر متن→input_ids→embedding→اطلاعات جایگاه→attention→خروجی را رسم و tokenizer را از آموزش مدل جدا کن.','برای A B C توضیح بده در decoder علّی جایگاه B به A و B می‌بیند ولی C را نمی‌بیند؛ ماسک padding وعلّی را یکی نگیر.','Encoder مثل BERT، decoder مثل GPT و encoder-decoder را از نظر هدف و ورودی/خروجی جدول کن.','برای تمرین tokenizer تنها بگیر؛ مدل بزرگ لازم نیست. نام checkpoint، revision و license آن را پیش از download بررسی کن.'],practice:['با AutoTokenizer برای bert-base-multilingual-cased فقط tokenizer را دریافت کن؛ revision قابل‌ردیابی و license را ثبت کن.','«سلام دنیا» و«Hello world» را encode و tokens، ids، attention_mask و length را با specialtokens ثبت کن.','با skip_special_tokens=True، decode را اجرا و تفاوت فاصله‌گذاری یا normalization بااصل را مشاهده کن؛ برابری کامل را فرض نکن.','دو متن ناهم‌اندازه را batch کن و padding/truncation/max_length را مشخص کن؛ تعداد کاراکتر و token را مقایسه کن.'],source:'hf',section:'Transformer models؛ Tokenizers؛ Handling multiple sequences',read:'معماری Transformer و کار tokenizer را بخوان؛ فعلاً حفظ فرمول همه مدل‌ها لازم نیست.',action:'نام checkpoint و ids دو زبان را همراه mask، specialtokens و length در Notebook ذخیره کن.',studyTask:'نقش token، embedding و attention را روی توالی A B C شرح بده.',task:'متن فارسی و انگلیسی را با tokenizer مشخص encode/decode کن.',input:'«سلام دنیا» و«Hello world» با bert-base-multilingual-cased',expected:'جدول tokens/ids/length واقعی اجرای خودت؛ تنظیم specialtokens روشن؛ در decoder علّی B نباید C را ببیند. عدد توکن از پیش تضمین نمی‌شود.',hint:'شناسه SEP/CLS یا همان specialtokens در طول کل شمرده می‌شوند؛ برای پایداری revision واقعی را در کد تحویلی ثبت کن.',pitfalls:['هر token یک کلمه یا کاراکتر نیست؛ نسبت طول فارسی/انگلیسی به tokenizer وابسته است.','decode ممکن است به‌علت normalization و فاصله‌گذاری دقیقاً رشته اولیه نباشد.'],code:'from transformers import AutoTokenizer\ntok = AutoTokenizer.from_pretrained("bert-base-multilingual-cased")\nfor text in ["سلام دنیا", "Hello world"]:\n    x = tok(text)\n    print(tok.convert_ids_to_tokens(x["input_ids"]))\n    print(x["input_ids"])\n    print(tok.decode(x["input_ids"], skip_special_tokens=True))'}
,{intro:['Pretraining وزن پایه را با هدف یادگیری از داده متن تخمین می‌زند؛ SFT از نمونه ورودی/پاسخ مطلوب استفاده می‌کند؛ PreferenceTuning ترجیح بین پاسخ‌ها را به‌کار می‌گیرد. Inference استفاده با وزن ثابت است و به‌تنهایی تغییر مدل یا آموزش جدید نیست.','Dataset کوچک هم به مجوز، کیفیت و تقسیم روشن نیاز دارد. نسخه‌های یک متن یا گفت‌وگو نباید در train و test پخش شوند. Checkpoint وضعیت ذخیره‌شده مدل است؛ epoch یک عبور از train و batch بخش کوچک‌تری از آن است.'],study:['برای چهار مرحله، هدف، نوع نمونه و تغییر یا عدم تغییر وزن را جدول کن؛ یک پاسخ چت دلیل fine-tuning نیست.','برای Shot ساختگی یک input و summary مرجع بنویس؛ summary نباید رویداد یا شخصیت تازه اضافه کند.','برای 100 نمونه و batch10 حدود 10step در epoch داریم با فرض نبود gradientaccumulation و حذف‌نکردن batch آخر؛ فرض‌ها را بنویس.','مدل پایه را پیش از آموزش با prompt و generation config ثابت روی validation بسنج و baseline ذخیره کن.'],practice:['رکوردهای ساختگی با id، input، target، source و license/وضعیت ساختگی بساز؛ اطلاعات واقعی استودیو وارد نکن.','خالی و تکراری پس از normalization را پیدا و تعداد قبل/بعد و دلیل حذف را گزارش کن؛ متن اصلی قابل ردیابی بماند.','نمونه‌های یک متن منبع یا سکانس را در همان split نگه دار؛ seed و id های train/validation/test ذخیره شوند.','baseline مدل کوچک را با config ثابت روی validation اجرا کن؛ اگر امکان ات اجرا نیست همان محدودیت را ثبت کن.'],source:'training',section:'Preprocess datasets؛ Training configuration؛ Evaluation',read:'آماده‌سازی dataset، tokenization و تعیین پارامتر آموزش را بخوان؛ فرمت داده باید با task و نوع مدل انتخابی سازگار باشد.',action:'schema input/target، گزارش پاک‌سازی و id تقسیم را پیش از training بساز و baseline را ذخیره کن.',studyTask:'یک نمونه Shot را به فرمت SFT و یک جفت Preference با chosen/rejected تبدیل کن.',task:'Dataset پاک و split غیر هم پوشان همراه baseline پیش از آموزش بساز.',input:'دو متن یکسان، یک input خالی و چند نمونه از یک Sequence',expected:'خالی و تکراری با دلیل حذف؛ منبع واحد درس هم جدا پخش‌نشود؛ SFT پاسخ مرجع و Preference دو جواب ترجیح‌دار دارد؛ baseline با config ذخیره شود.',hint:'normalization را قبل تشخیص تکرار انجام بده ولی اصل رکورد را نگه دار؛ تقسیم گروهی را تنها random سطر انجام نده.',pitfalls:['تصادفی‌کردن سطرها بدون کنترل منبع جلوی leakage را نمی‌گیرد.','checkpoint خاص با نام مدل پایه یکی نیست؛ revision و وزن واقعی را ثبت کن.']}
,{intro:['Fine-tuning وزن‌هایی را برای task تازه تغییر می‌دهد. LoRA اغلب وزن پایه را ثابت و پارامترهای کم‌رتبه را آموزش می‌دهد؛ QLoRA از پایه کم‌دقت همراه adapter بهره می‌گیرد. Quantization کاهش precision نمایش عددی است و به‌تنهایی معادل آموزش یا یادگیری جدید نیست.','حافظه فقط اندازه فایل وزن نیست؛ activation، gradient، optimizer، batch و طول توالی هم مهم‌اند. با CPU و مدل کوچک می‌توان روش را تمرین کرد. انتخاب مدل چندمیلیاردپارامتری صرفاً به‌خاطر 4bit بودن، تضمین جا شدن در VRAM نیست.'],study:['full fine-tuning، LoRA، QLoRA و quantization را از نظر پارامتر آموزش‌پذیر، پایه ثابت و precision جدول کن.','مدل کوچک متناسب با تمرین راهنما انتخاب کن؛ task، license، revision و تعداد پارامتر را ثبت کن. خلاصه‌ساز StudioFlow لزوماً همین مدل نیست.','بودجه num_samples، batch، max_length، lr، epoch و حد زمان را بنویس و یک batchforward/backward برای سازگاری اجرا کن.','شرط توقف validation بدتر یا OOM را تعیین و checkpoint را از validation انتخاب کن، نه test.'],practice:['model/datasetrevision، split، seed، tokenization و baseline ثابت را آماده کن؛ baseline باید پیش از آموزش باشد.','اجرای محدود با CPU و مدل کوچک یا GPU واقعی انجام بده؛ فقط روش واقعاً اجراشده را LoRA/QLoRA بنام.','step، train loss، validation metric، زمان و RAM/VRAM واقعی را ثبت کن؛ peak را با حافظه پایان اشتباه نگیر.','weights یا adapter را با base_revision، tokenizer و config ذخیره و یک sample را پس از reload پیش‌بینی کن.'],source:'training',section:'Fine-tuning؛ Training configuration؛ Evaluation',read:'یک روش Trainer یا حلقه Native را انتخاب و با API نسخه نصب‌شده جلو برو؛ مقایسه همه روش‌ها به‌معنی اجرای همه نیست.',action:'آزمایش کوچک با config ثبت‌شده بساز و در صورت adapter، مدل پایه و adapter را جدا مستند کن.',studyTask:'ادعای «مدل 4bit حتماً با 6GB فاین‌تیون می‌شود» را با اجزای حافظه نقد کن.',task:'یک fine-tuning محدود با log، config و checkpoint قابل reload اجرا کن.',input:'مدل و داده کوچک؛ بودجه step و طول توالی کوتاه؛ CPU در نبود GPU',expected:'train/validation، زمان، حافظه و reload واقعی؛ یا گزارش علت اجرای ناموفق. بهبود و جا گرفتن مدل از پیش تضمین نشده است.',hint:'با 100 تا چند صد نمونه شروع کن؛ فاین‌تیون نمونه طبقه‌بند کوچک هم برای فهم حلقه معتبر است.',pitfalls:['Quantization به‌تنهایی معادل یادگیری وزن نیست.','کم‌شدن train loss بدون validation هم‌شرایط، شاهد بهبود مدل نیست.']}
,{intro:['مقایسه پیش و پس باید با همان test، preprocessing، سنجه و generation config انجام شود. عوض‌شدن نمونه یا حداکثر طول تولید علت تفاوت را مبهم می‌کند. test پس از استفاده برای انتخاب تنظیم دیگر آزمون دست‌نخورده نیست.','گزارش نهایی موفقیت و شکست را نشان می‌دهد. مدل جدید ممکن است سنجه بهتری داشته باشد اما ادعای جعلی بسازد یا اطلاعات حساس را حفظ کند. در آزمایش کوچک، «بهبود ندیدم» هم نتیجه علمی قابل‌ارائه است اگر شواهد و روش روشن باشند.'],study:['checkpoint پایه و جدید، test، prompt، max_length و سنجه را پیش از اجرا نهایی ثابت و ثبت کن.','برای طبقه‌بندی accuracy و گروه خطا؛ برای خلاصه‌سازی معیار حفظ واقعیت را تعریف کن. شباهت خودکار به‌تنهایی صحت واقعیت نیست.','دلیل انتخاب checkpoint از validation را بنویس؛ با test تنظیمات جدید انتخاب نکن.','تعداد، دامنه زبان، طول ورودی، زمان و حافظه را کنار سنجه بنویس؛ اختلاف کوچک را قطعیت علمی ننام.'],practice:['model-card.md، data-manifest.json، config.json، metrics.json و examples بساز؛ checkpoint بزرگ را بی‌دلیل در Git نگذار.','دو checkpoint را روی همان sample_id ها و با همان config اجرا و خروجی خام را ذخیره کن.','جدول سنجه پیش/پس، n، زمان و حافظه با حداقل دو نمونه خطای واقعی تهیه کن.','دستور README را از محیط تازه اجرا کن؛ اگر عدد نوسان دارد دامنه و دلیل واقعی را ثبت کن.'],source:'training',section:'Evaluation؛ prediction؛ ذخیره checkpoint و training workflow',read:'روش محاسبه metric را با مدل خودت تطبیق بده؛ metric روی logits یا decodedtext مناسب task اعمال شود.',action:'تابع ارزیابی واحد را برای مدل پایه وفاین‌تیون استفاده کن و خروجی raw را کنار metric نگه دار.',studyTask:'چرا مقایسه 50 متن کوتاه baseline با 20 متن بلند مدل جدید قابل‌دفاع نیست؟',task:'بسته ارزیابی قابل بررسی پیش/پس را تحویل بده.',input:'دو checkpoint، test ثابت و config مشخص',expected:'جدول واقعی سنجه و زمان، rawoutput، نمونه شکست، manifest و دستور اجرا؛ اگر مدل جدید بدتر است همان ثبت شود.',hint:'اعداد مثال این صفحه نتیجه پروژه نیستند؛ از لاگ اجرای خودت گزارش بساز.',pitfalls:['انتخاب فقط خروجی‌های خوب برای demo کیفیت کل را اندازه نمی‌گیرد.','تغییر prompt هم زمان با fine-tuning علت بهبود را نامعلوم می‌کند.']}
,{intro:['قابلیت AI نسخه اول StudioFlow فقط خلاصه‌سازی شرح Shot است. ورودی متن ساختگی و خروجی چند جمله کوتاه است که باید نام شخصیت، عمل و پایان رویداد را حفظ کند. Tag، تولید Task و تحلیل گزارش گزینه‌های آینده‌اند و در این خروجی اضافه نمی‌شوند.','قرارداد خلاصه‌ساز باید حدود و کیفیت را روشن کند:حداکثر طول، مهلت پاسخ، رفتار متن خالی و خطا. مدل آماده یا API با اقدام صریح کاربر برای این پروژه کافی است؛ آموزش از صفر لازم نیست و داده واقعی استودیو بدون اجازه ارسال نمی‌شود.'],study:['schema ورودی description و خروجی summary، model_version و request_id را بنویس؛ version باید به مدل و config واقعی قابل ردیابی باشد.','برای تمرین حدود 1 تا 2000 کاراکتر، حداکثر 3 جمله و timeout10 ثانیه انتخاب کن؛ این‌ها فرض تمرین‌اند و بعداً با آزمایش اصلاح می‌شوند.','مدل کوچک محلی یا provider خارجی را از نظر زبان، license، حافظه، هزینه و حریم خصوصی مقایسه کن؛ کلید API در frontend یا Git قرار نگیرد.','معیار موفقیت را حفظ نام‌ها و واقعیت‌ها تعریف کن؛ timeout یا unavailable نباید ویرایش اصلی Shot را از کار بیندازد.'],practice:['ده Shot ساختگی با حالت کوتاه، چندشخصیتی، ترتیب زمانی، نام فارسی و ابهام بنویس؛ متن واقعی سفارشی ارسال نکن.','برای هر نمونه ستون must_keep شامل نام‌ها، عمل اصلی و نتیجه بنویس؛ مرجع می‌تواند چند بیان درست داشته باشد.','به حفظ نام، پوشش رویداد و ندادن ادعای جدید هرکدام 0 یا 1 بده؛ هر hallucination را حتی با نمره کل خوب شکست مهم ثبت کن.','یک خلاصه مردود که شخصیت یا عمل جدید می‌سازد بنویس و آن را به fixture آزمون ارزیابی تبدیل کن.'],source:'hf',section:'Transformers pipelines؛ استفاده از مدل‌های آماده و انتخاب task',read:'بخش pipeline و انتخاب مدل برحسب task را بخوان؛ پشتیبانی فارسی و خلاصه‌سازی را از کارت همان مدل منتخب بررسی کن.',action:'یک candidate با مجوز، revision و زبان ثبت کن؛ صرف وجود pipeline را تضمین خلاصه فارسی ندان و ابتدا با Shot ساختگی بسنج.',studyTask:'schema محدود خلاصه‌ساز را با خطاهای empty، too_long، timeout و unavailable تعریف کن.',task:'ده Shot ساختگی با must_keep، مرجع و یک خلاصه مردود بساز.',input:'«لیلا چراغ را خاموش می‌کند. امیر در را باز می‌کند و هر دو خارج می‌شوند.»',expected:'must_keep شامل لیلا/امیر، خاموش‌کردن، بازکردن و خروج است؛ «سارا پنجره را می‌بندد» به علت ادعای جدید رد می‌شود. ده sample_id و معیار ثبت شود.',hint:'خلاصه را جایگزین خودکار شرح اصلی نکن؛ کاربر باید پیش از استفاده نتیجه را بازبینی کند.',pitfalls:['آموزش LLM از صفر شرط ساخت این قابلیت محدود نیست.','روان‌بودن خلاصه به‌معنی صحت واقعیت و نداشتن hallucination نیست.']}
,{intro:['ارزیابی خلاصه‌ساز مقایسه خروجی با موارد ضروری متن است. شباهت واژه به‌تنهایی صحت را نمی‌سنجد:«چراغ روشن می‌شود» و«چراغ خاموش می‌شود» کلمات مشترک زیادی دارند اما معنای شان مخالف است. فاعل، عمل، مفعول و ترتیب باید جدا بررسی شوند.','سرویس Python پشت یک قرارداد محدود قرار می‌گیرد. Go اول هویت و مجوز Shot را بررسی می‌کند و فقط پس از کلیک کاربر متن لازم را می‌فرستد. timeout یا نبود مدل نباید ثبت ویرایش اصلی Shot را متوقف کند؛ مرز خطای محصول و AI جدا است.'],study:['نام مدل، revision، prompt، temperature یا تنظیمات تولید، حد طول و نسخه مجموعه ده‌نمونه‌ای را ثابت و ثبت کن.','خروجی خام ده sample را به id وصل کن؛ پاسخ‌ندادن provider را با خطا و زمان ثبت کن نه خلاصه ساختگی.','معیار حفظ نام، رویداد، ندادن ادعای جدید و طول را روی هر نمونه اعمال و یک ردیف شکست را با عبارت غلط توضیح بده.','تعداد موفق، خطای واقعیت، timeout و خروجی خالی را جدا گزارش کن؛ ده‌نمونه خوب تضمین تمام حالت‌ها نیست.'],practice:['POST /summarize با description و summary/model_version طراحی کن؛ برای آزمون قرارداد ابتدا stub محلی قابل کنترل بساز.','خالی، غیر رشته و طول زیاد را پیش از مدل رد کن؛ HTTPclient در Go deadline داشته باشد و providererror به پیام روشن تبدیل شود.','در پنل دکمه صریح«خلاصه کن» بگذار؛ هنگام تایپ متن ارسال نشود و شرح اصلی فقط با انتخاب کاربر تغییر کند.','Python را در محیط آزمون خاموش کن؛ ویرایش Shot همچنان ذخیره شود و بخش AI پیام unavailable بدهد.'],source:'hf',section:'Pipelines و tokenization برای inference؛ محدودیت‌های Model Card',read:'روش pipeline مدل منتخب و حد طول ورودی را بخوان؛ زبان، task و preprocessing باید با همان checkpoint سازگار باشند.',action:'مدل را یک‌بار در startup بارگذاری کن و preprocessing آزمایش را بی‌تغییر به سرویس منتقل کن؛ خروجی واقعی را با fixture قرارداد مقایسه کن.',studyTask:'خلاصه درست و وارونه را با معیار واقعیت امتیاز بده.',task:'یک درخواست موفق و یک قطع سرویس را از Go/React تا Python آزمایش کن.',input:'متن«لیلا چراغ را خاموش می‌کند.»؛ خلاصه A «لیلا چراغ را خاموش کرد.»؛ B «لیلا چراغ را روشن کرد.»',expected:'A رویداد اصلی را حفظ و B عمل را وارونه می‌کند؛ موفق schema معتبر و version دارد؛ قطع Python پیام AIunavailable می‌دهد ولی ذخیره Shot کار می‌کند.',hint:'request_id در Go و Python به ردیابی لاگ کمک می‌کند؛ متن خصوصی و کلید را log نکن.',pitfalls:['HTTP200 با متن خطا داخل summary موفقیت قابلیت نیست.','کلید provider هرگز در React یا JavaScript مرورگر قرار نگیرد.']}
,{intro:['قابلیت AI باید محدودیت قابل خواندن داشته باشد:چه زبان و نوع متنی آزمایش‌شده، چه‌داده‌ای ارسال می‌شود و کاربر چیزی را چگونه تأیید می‌کند. مثال خطای واقعی از وعده«همیشه درست» مفیدتر است و مانع اعتماد بی‌جا به خلاصه می‌شود.','تست شکست فقط کیفیت مدل را نمی‌سنجد؛ مقاومت سرویس را هم بررسی می‌کند. input بلند باید پیش از محاسبه رد شود، JSON خراب نباید به summary ظاهراً موفق تبدیل شود و قطع AI نباید صفحه تولید را از کار بیندازد.'],study:['AI_LIMITATIONS.md با revision، داده ارزیابی، زبان، حد ورودی، schema و روش استفاده از خلاصه بنویس.','چند درخواست ساختگی ثابت بفرست و زمان میانه/بدترین را ثبت کن؛ هزینه را فقط از مصرف واقعی یا تعریف مشخص گزارش کن، نه حدس.','از خروجی واقعی نمونه حذف نام، عمل جعلی یا متن بسیار طولانی انتخاب و پیام محدودیتش را برای کاربر بنویس.','در networklog بررسی کن بارگذاری صفحه و تایپ شرح ارسال AI ناخواسته ندارد و فقط کلیک endpoint را صدا می‌زند.'],practice:['سه fixture بساز:متن بیش ازحد، پاسخ JSON ناقص یا summary غیر رشته و endpoint قطع‌شده.','در محیط آزمایش client مدل را با stub عوض کن تا timeout و پاسخ خراب قابل تکرار باشند؛ آن را اجرای واقعی مدل معرفی نکن.','در API کد/schema خطا و در UI پیام روشن بررسی کن؛ traceback یا secret افشا نشود و ذخیره Shot ادامه یابد.','هر fixture را به test نام‌دار با expectedstatus/schema تبدیل کن و سناریوی قبلی موفقیت را هم دوباره اجرا کن.'],source:'python',section:'Errors and Exceptions؛ مدیریت خطا در مرز سرویس و آزمون تابع',read:'Handling Exceptions و جداسازی خطای انتظاری مثل ValueError از خطای داخلی را بخوان؛ برای test ابزار stack خودت را انتخاب کن.',action:'client مدل را به وابستگی جدا تبدیل کن تا پاسخ خراب و قطع سرویس با بدل‌آزمایشی قابل‌کنترل باشد.',studyTask:'ادعای «AI همیشه خلاصه درست می‌دهد» را به گزارش دارای دامنه، سنجه و محدودیت تبدیل کن.',task:'سه شکست طول ورودی، پاسخ خراب و قطع سرویس را با test قابل تکرار بررسی کن.',input:'شرح 2001 کاراکتری با حد 2000؛ {"summary":null}؛ endpoint غیر فعال',expected:'اولی پیش از مدل رد؛ دومی خطای schema پاسخ؛ سومی unavailable. ذخیره Shot بدون AI در هر سه ممکن است و داده حساس در خطا نیست.',hint:'stub فقط رفتار سیستم در شکست را می‌سنجد؛ کیفیت مدل واقعی نیاز به خروجی واقعی دارد.',pitfalls:['سه‌بار کلیک نباید سه درخواست هم زمان نامحدود و هزینه‌زا بسازد.','نتیجه بدل‌آزمایشی را به‌عنوان سنجه کیفیت مدل واقعی گزارش نکن.']}
,{intro:['پورتفولیو باید فرق شبکه‌ای که خودت آموزش داده‌ای، مدلی که fine-tune کرده‌ای و API مدلی که مصرف کرده‌ای را روشن بگوید. MNIST شاهد فهم حلقه آموزش است؛ خلاصه‌ساز StudioFlow شاهد قرارداد، ارزیابی و مهندسی خطاست. این کارها توانایی یکسانی را اثبات نمی‌کنند.','توضیح فنی از نمونه واقعی شروع می‌شود:ورودی چگونه Tensor می‌شود، چرا loss انتخاب شده و کجای کار وزن تغییر می‌کند. اجرای Notebook آماده به‌تنهایی تخصص ML یا LLM نیست؛ عنوان و ادعای رزومه را بر اساس نمونه قابل نمایش انتخاب کن.'],study:['برای MNIST، fine-tuning و خلاصه‌ساز لینک کد، config، داده ارزیابی، نتیجه واقعی و یک خطا را جمع کن.','در هر پروژه بگو مدل خود تعریف‌شده، پایه بارگذاری‌شده یا API بیرونی است؛ جمله کلی«مدل AI ساختم» را دقیق کن.','برای data، trainloop، evaluation، deployment و مدیریت خطا سطح‌مستقل/با راهنما/اجرا نشده را با شاهد ثبت کن.','دو جمله شرح انگلیسی با task، stack و روش ارزیابی واقعی بنویس؛ اعداد منبع را نتیجه خودت معرفی نکن.'],practice:['بدون راهنما مسیر images→logits→loss→gradient→step یک batch پروژه خودت را توضیح بده.','به چهار پرسش پاسخ بده:چرا CrossEntropy روی logits؟ چرا zero_grad؟ چرا eval/no_grad؟ چرا test برای انتخاب lr نیست؟','یک bug واقعی مثل shape یا reload را با commit/test روایت کن؛ نشانه، قرارداد نقض‌شده و اصلاح را توضیح بده.','توضیح را ضبط یا متن‌نویسی و ابهام‌ها را علامت بزن؛ برای قسمتی که واقعاً پاسخ نداری سطح«با راهنما» ثبت کن.'],source:'torch',section:'Tensors؛ Neural Network؛ Autograd؛ Optimization؛ Save and Load',read:'این بار ابتدا پاسخ مستقل بده و فقط مبحث ابهام را برای تصحیح مرور کن؛ بازخوانی همه دوره جای ارزیابی نیست.',action:'هر پاسخ loss/gradient/evaluation را به نام تابع و سلول خودت وصل کن و شواهد آن را در پورتفولیو بگذار.',studyTask:'برای سه ادعای آموزش MNIST، fine-tuning و اتصال خلاصه‌ساز شواهد لازم را فهرست کن.',task:'شرح مستقل حلقه آموزش و رفع یک bug واقعی را تحویل بده.',input:'یک batchMNIST و کد خودت؛ بدون منبع باز',expected:'inputshape، logits، loss، gradient و step با علت تفکیک validation شرح داده شود؛ bug با test قبل/بعد شاهد داشته باشد؛ ادعاهای بی‌شاهد حذف یا اصلاح شوند.',hint:'اگر کد را تنها با الگو اجرا می‌کنی، هنوز می‌توانی شاهد«با راهنما» ثبت کنی؛ تسلط ساختگی علامت نزن.',pitfalls:['اتصال به مدل آماده معادل آموزش وزن آن نیست.','accuracy کپی‌شده از درس منبع، نتیجه آزمایش خودت نیست.']}
,{intro:['ممیزی آزمایش یعنی یک عدد گزارش را تا data، model، config و code دنبال کنی. ادعای بهبود بدون baseline یا split روشن قابل بررسی نیست. گاهی رفع شکاف نیازی به آموزش دوباره ندارد و فقط باید دامنه ادعا را بر اساس شواهد کمتر کنی.','تکرار آزمایش باید محدود و قابل پایان باشد. پرسش، سنجه، زمان و حافظه را پیش از تکرار تعیین کن؛ اگر امکان اجرا نشد، ثبت دقیق محدودیت، نسخه بسته و پیام خطا از ساختن نتیجه مطلوب ارزشمندتر است.'],study:['یک جمله عدد دار از گزارش پیش/پس انتخاب کن و checkpoint ها، idtest، config و کد محاسبه سنجه آن را پیدا کن.','جدول data_revision، model_revision، code_commit و configfile برای هر metric بساز؛ نبود اطلاعات را unknown بنویس.','prompt، طول تولید، device، سنجه و مجموعه نمونه پیش/پس را مقایسه و تفاوت‌ها را عامل دخیل گزارش کن.','ادعای فاقد شاهد را «بهبود تأیید نشده»یا«اجرا نشده» اصلاح کن؛ عدد واقعی را حذف نکن ولی ادعای بیشتر نساز.'],practice:['یک شکاف کوچک مثل reload مستقل یا محاسبه دوباره سنجه روی 20sample ثابت انتخاب و پرسش را اول Notebook بنویس.','بودجه تمرینی 20 نمونه و 10 دقیقه با CPU مشخص تعیین کن؛ GPU نداشته را اجراشده ننویس.','با checkpoint/config ثابت اجرا و خروجی خام و خطا ذخیره کن؛ تا پیدا شدن نتیجه دلخواه مدام شرایط را عوض نکن.','اگر dataset یا حافظه در دسترس نیست نام مانع، پیام خطا و قدم بعد را ثبت کن؛ command و id ها برای بازاجرا بمانند.'],source:'training',section:'Evaluation؛ ذخیره checkpoint؛ ثبت training configuration',read:'مسیر metric تا prediction و config را بر اساس فایل‌های واقعی خودت بررسی کن؛ فهرست Hyperparameter خالی جای گزارش آزمایش نیست.',action:'یک metric را به فایل داده، checkpoint، config و commit متصل و حلقه کوچک ارزیابی را مستقل اجرا کن.',studyTask:'گزارش accuracy=0.82 بدون baseline و تقسیم را به ادعای قابل‌دفاع تبدیل کن.',task:'یک آزمایش کوچک ناقص را تکرار یا مانع آن را دقیق مستند کن.',input:'checkpoint مشخص و 20sample ثابت؛ بودجه 10 دقیقه به‌عنوان فرض تمرین',expected:'command، config، خروجی واقعی و metric؛ یا خطا و محدودیت واقعی با قدم بعد. نبود baseline یعنی بهبود قابل تأیید نیست، نه اینکه باید عدد ساخت.',hint:'برای اتمام این کار به خرید GPU یا مدل جدید نیاز نیست؛ کوچک‌ترین شکاف اثبات‌پذیر را انتخاب کن.',pitfalls:['ترمیم گزارش با عدد ساختگی شکاف را بدتر می‌کند.','تکرار روی dataset متفاوت پاسخ همان پرسش آزمایش اول را به‌تنهایی نمی‌دهد.']}
,{intro:['ارزیابی نهایی فهم AI باید توضیح را به شاهد کد وصل کند. «loss حساب شد» کافی نیست؛ باید بگویی با کدام label، چرا این loss و چه‌چیزی وزن را عوض می‌کند. در مدل زبانی نیز tokenization، attention، SFT و inference نقش‌های جدا دارند.','روایت فنی باید مشاهده را از علت احتمالی جدا کند. «با batch بزرگ‌تر OOM دیدم» مشاهده است و«activation حافظه را پر کرد» فرضیه محتاج اندازه‌گیری. موفقیت و شکست را با حدود توانایی واقعی توضیح بده و از آزمایش کوچک ادعای تسلط کلی نساز.'],study:['بدون منبع به پنج پرسش پاسخ ده:مسیر MNIST تا logit؛ چرا validation بدون step؛ فرق SFT/inference؛ فرق token/embedding؛ decoder علّی چه چیزی را نمی‌بیند؟','برای هر پاسخ سلول Notebook، تابع یا لاگ با id/commit پیدا کن؛ پاسخ حفظی بدون شاهد را سطح‌مستقل ننام.','ورودی shape نادرست یا رشته خالی خلاصه‌ساز را وارد و کنترل قرارداد را از test خودت شرح بده.','ابهام‌های پاسخ را با تمرین و تاریخ مرور بعدی ثبت کن؛ این ارزیابی پایان آموزش AI را تضمین نمی‌کند.'],practice:['یک موفقیت و یک شکست واقعی از MNIST، fine-tuning یا خلاصه‌ساز انتخاب کن؛ هرکدام شاهد قابل نمایش داشته باشد.','در روایت پنج‌دقیقه‌ای مسئله، روش، شاهد، محدودیت و قدم بعد را پوشش بده؛ واحد زمان/حافظه و شرایط را روشن کن.','برای موفقیت یک عامل رقیب و برای شکست آزمایش تمایزدهنده پیشنهاد کن؛ نبود شاهد را با حدس قطعی پُر نکن.','متن یا ضبط روایت و مرجع پروژه را به ارزیابی مهارت وصل کن و فقط سطحی را ثبت کن که در این مصاحبه توانسته‌ای نشان بدهی.'],source:'hf',section:'Transformer models؛ Tokenizers؛ Fine-tuning و مسیر استفاده از مدل',read:'پس از پاسخ مستقل، فقط بخش ابهام در نقش tokenizer، decoder و training را مرور کن؛ برای gradient به کد PyTorch خودت رجوع کن.',action:'یک نقشه متن→token→مدل→خروجی بکش و SFT را بیرون از مسیر inference مشخص کن؛ شاهد پروژه را کنار هر پاسخ بگذار.',studyTask:'فرق optimizer.step در MNIST با generate بدون step در مدل آماده را توضیح بده.',task:'دو روایت شواهد دار موفقیت و شکست را در پنج‌دقیقه ارائه کن.',input:'یک metric یا bugfix واقعی موفق؛ یک failedrun یا خلاصه غلط واقعی',expected:'هر روایت مشاهده، مدرک، علت احتمالی، محدودیت و قدم بعد دارد؛ پنج پرسش فهم با کد مرتبط پاسخ دارند؛ اجرای انجام‌نشده موفق ثبت نشود.',hint:'«هنوز اجرا نکرده‌ام» را صادقانه ثبت کن و برایش یک آزمایش بعدی مشخص پیشنهاد بده؛ وجود PyTorch در کد به‌تنهایی گواه training نیست.',pitfalls:['تکمیل تیک‌ها تخصص ML یا استخدام را تضمین نمی‌کند.','موفقیت یک آزمایش کوچک مجوز تعمیم به همه داده‌ها و سخت‌افزار ها نیست.']}
];

export const aiLessons:Record<string,LessonGuide>={};
for(let i=0;i<topics.length;i++){
 const t=topics[i],week=i+1;
 const resource={title:titles[t.source],url:urls[t.source],focus:t.section,read:t.read,action:t.action};
 const exercise={task:t.task,input:t.input,expected:t.expected,hint:t.hint};
 const shared={resourceSections:[resource],pitfalls:t.pitfalls,...(t.code?{example:{language:'python',code:t.code,explanation:'این مثال کوچک برای فهم قرارداد همین درس است؛ آن را اجرا کن، خروجی را پیش‌بینی کن و سپس ورودی یا پارامتر مشخص‌شده در تمرین را تغییر بده.'}}:{})};
 aiLessons[`w${week}-ai-study`]={...shared,intro:t.intro,steps:t.study.map((body,j)=>({title:`گام ${j+1}`,body})),exercise:{...exercise,task:t.studyTask},checks:[t.studyTask,t.expected]};
 aiLessons[`w${week}-ai-practice`]={...shared,intro:[`این فعالیت، مفاهیم همین هفته را به خروجی قابل بررسی تبدیل می‌کند: ${t.task} ${t.intro[0]}`,t.intro[1]],steps:t.practice.map((body,j)=>({title:`مرحله ${j+1}`,body})),exercise,checks:[t.expected,t.practice[t.practice.length-1]]};
}
